import{b as n,J as r}from"./app-6658f0c3.js";import{d as a}from"./utils-b3a0ca16.js";const l=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: видеокарты",content:"Хотите пройти быстрое обучение по видеокартам?",placement:"center"},{target:"#part-guide-overview",title:"Видеокарта",content:"Это высокопроизводительное устройство, которое преобразует данные в изображение на мониторе. Широко используется для майнинга за счёт большого кол-ва ядер в отличии от процессора.",placement:"bottom"},{target:"#part-guide-vendor",title:"Вендор",content:"Видеокарты производит большое количество вендоров, то есть производителей.",placement:"bottom"},{target:"#GPU-guide-VRAM-size",title:"Кол-во памяти",content:"Для майнинга нужно довольно большое кол-во видеопамяти. Чем её большее, тем лучше. Желательно покупать карты с 6+ или хотя бы 4+ ГБ памяти.",placement:"bottom"},{target:"#GPU-guide-VRAM-bit",title:"Разрядность шины памяти",content:"Влияет на скорость обмена данными между чипом и памятью. Чем выше битность, тем лучше.",placement:"bottom"},{target:"#GPU-guide-frequency",title:"Частота видеочипа",content:"Кол-во операций, которое выполняет видеокарта за 1 секунду. Обычно у OC (разогнанных) видеокарт частота немного выше, что даёт небольшой прирост хешрейта.",placement:"bottom"},{target:"#GPU-guide-power",title:"Потребление энергии",content:"Показывает, сколько энергии потребляет видеокарта. Учитывайте это при выборе блока питания!",placement:"bottom"},{target:"#GPU-guide-fans-count",title:"Кол-во вентиляторов",content:"Обычно видеокартам нужно хорошее охлаждение. Чем больше вентиляторов, тем видеокарта будет меньше греться. Также существуют карты с водяным охлаждением.",placement:"bottom"},{target:"#part-guide-overview",title:"Хешрейт",content:"Главная характеристика для майнера - чем производительнее видеокарта, тем больше у неё хешрейт, и, соответственно, прибыль. Хешрейт вы можете найти в интернете (Алгоритм ETHASH).",placement:"bottom"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете о том, какие бывают видеокарты, и чем они отличаются. Совет: для того, чтобы играть было интереснее, покупайте разные модели видеокарт, стройте интересные и разнообразные риги!",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),s=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: процессоры",content:"Хотите пройти быстрое обучение по процессорам?",placement:"center"},{target:"#part-guide-overview",title:"Процессор",content:"Ядро любого компьютера, предназначен для обработки информации и управления другими устройствами. Чем мощнее ваш риг, тем сильнее будет нагружен процессор.",placement:"bottom"},{target:"#part-guide-vendor",title:"Вендор",content:"Существует 2 наиболее распространённых производителя процессоров: Intel и AMD.",placement:"bottom"},{target:"#CPU-guide-socket",title:"Сокет",content:"Это разъем, место на материнской плате компьютера, куда вставляется процессор. Процессор, прежде чем он будет установлен в материнскую плату, должен подходить ей по сокету.",placement:"bottom"},{target:"#CPU-guide-cors",title:"Кол-во ядер",content:"Это кол-во вычислительных блоков процессора. Чем их больше, тем лучше. (P.s у Intel 12-13 поколения 2 энергоэффективных ядра в нашем майнинг алгоритме приравниваются к 1 производительному ядру)",placement:"bottom"},{target:"#CPU-guide-threads",title:"Кол-во потоков",content:'Это кол-во "виртуальных ядер" процессора. Чем их больше, тем лучше.',placement:"bottom"},{target:"#CPU-guide-frequency",title:"Частота",content:"Грубо говоря, показывает, сколько операций в секунду может выполнить процессор. Частота у разогнанных процессоров больше, чем у обычных (Разогнанные процессоры у Intel с индексом KF, а у AMD - X)",placement:"bottom"},{target:"#CPU-guide-power",title:"Потребление энергии",content:"Показывает, сколько ватт энергии потребляет процессор. Влияет на загрузку блока питания.",placement:"bottom"},{target:"#CPU-guide-TDP",title:"Тепловыделение",content:"Кол-во теплоты, которое выделяет процессор.",placement:"bottom"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете немного больше о процессорах, и чем они отличаются.",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),c=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: мат.платы",content:"Хотите пройти быстрое обучение по материнским платам?",placement:"center"},{target:"#part-guide-overview",title:"Материнская плата",content:"Это печатная плата, в которую вставляются все основные комплектующие: процессор, ОЗУ, видеокарта, накопители и другие устройства. Также видеокарты подключаются к компьютеру с помощью райзеров, если не хватает слотов PCIe.",placement:"bottom"},{target:"#motherboard-guide-socket",title:"Сокет",content:"Это гнездо для процессора, в него можно установить только процессор, совпадающий по сокету.",placement:"auto"},{target:"#motherboard-guide-sockets-count",title:"Кол-во сокетов",content:"Существуют материнские платы, в которые можно вставить не 1, а 2 процессора.",placement:"auto"},{target:"#motherboard-guide-chipset",title:"Чипсет",content:"Это набор микросхем для выполнения определенных задач, например, разные возможности биоса. В игре от чипсета зависит макс. TDP процессора. Обычно Z и X чипсет используется для разогнанных процессоров. Также у чипсета Intel H всего 2 разъёма ОЗУ.",placement:"auto"},{target:"#motherboard-guide-max-CPU-TDP",title:"Макс. TDP процессора",content:"Максимальное TDP процессора, которое могут выдержать цепи питания мат. платы. Если установить в неё процессор с большим TDP, чем допустимо, и загрузить его, то материнская плата может сгореть.",placement:"auto"},{target:"#motherboard-guide-RAM-compatibility",title:"Тип поддерживаемой памяти",content:"Показывает то, какую ОЗУ можно установить в эту материнскую плату. Например, DDR3 ОЗУ нельзя установить в слот DDR4",placement:"auto"},{target:"#motherboard-guide-RAM-slots",title:"Количество слотов памяти",content:"Показывает, сколько модулей ОЗУ можно установить в мат. плату. При этом учитывается именно кол-во модулей (в комплекте может быть несколько модулей)",placement:"auto"},{target:"#motherboard-guide-RAM-channels",title:"Количество каналов памяти",content:"Это поддержка работы ОЗУ, при котором осуществляется работа нескольких каналов памяти. Чем больше каналов, тем больше производительность ОЗУ, ведь шина данных увеличивается кратно кол-ву каналов.",placement:"auto"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете, какие бывают материнские платы, и чем они отличаются!",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),i=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: ОЗУ",content:"Хотите пройти быстрое обучение по оперативной памяти (ОЗУ)?",placement:"center"},{target:"#part-guide-overview",title:"Оперативная память",content:"Это энергозависимое запоминающее устройство, которое хранит выполняемый машинный код. В игре загрузка ОЗУ пропорциональна хешрейту рига. Чем мощнее видеокарты, тем производительнее должна быть ОЗУ.",placement:"bottom"},{target:"#RAM-guide-RAM-type",title:"Тип памяти",content:"Это, грубо говоря, поколение оперативной памяти. В материнскую плату DDR4 можно вставить только память DDR4, то есть тип DDR должен совпадать!",placement:"auto"},{target:"#RAM-guide-RAM-size",title:"Объём памяти",content:"Кол-во данных, которые можно хранить в оперативной памяти. Сильно влияет на общую производительность ОЗУ.",placement:"auto"},{target:"#RAM-guide-RAM-channels",title:"Кол-во модулей в комплекте",content:"Если материнская плата поддерживает многоканальный режим работы, то производительность ОЗУ будет выше, если кол-во модулей >= кол-ву каналов мат.платы.",placement:"auto"},{target:"#RAM-guide-RAM-frequency",title:"Частота",content:"Показывает кол-во циклов записи/считывания в секунду. Довольно сильно влияет на общую производительность ОЗУ.",placement:"auto"},{target:"#part-guide-overview",title:"Производительность ОЗУ",content:"Зависит от характеристик ОЗУ и влияет на загрузку видеокарт. Если мощность видеокарт (хешрейт) слишком высокий, то производительность рига будет упираться в ОЗУ, видеокарты будут недогружены и выдавать неполный хешрейт.",placement:"auto"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете больше. Интересный факт: в игре можно собрать риг на 2Тб ОЗУ)",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),u=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: блоки питания",content:"Хотите пройти быстрое обучение по блокам питания (БП)?",placement:"center"},{target:"#part-guide-overview",title:"Блок питания",content:"Это источник питания компьютера и его компонентов, он преобразует переменный ток из сети в постоянный ток разного напряжения для разных компонентов ПК.",placement:"bottom"},{target:"#part-guide-vendor",title:"Вендор",content:"Существует множество производителей блоков питания. Например, БП от Aerocool довольно плохие, а Seasonic, Super Flower являются гарантом качества.",placement:"bottom"},{target:"#part-guide-vendor",title:"Вендор",content:"Лучше покупать БП проверенных производителей. Из-за некачественного блока питания могут сломаться другие комплектующие!",placement:"bottom"},{target:"#PSU-guide-power-supply",title:"Мощность",content:"Это заявленная производителем мощность. Сумма потребления энергии устройств ПК (рига) не должна превышать мощность БП, а лучше, чтобы был запас по энергии!",placement:"bottom"},{target:"#PSU-guide-efficiency",title:"Сертификат 80 PLUS",content:'Показывает КПД БП. Коротко, БП с плохим сертификатом или без него потребляют из розетки больше ватт, чем отдают. Подробнее читайте в обучении, раздел "Для математиков".',placement:"bottom"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете больше о Блоках питания. Подходите к выбору тщательно!",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),p=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: вентиляторы",content:"Хотите пройти быстрое обучение по вентиляторам?",placement:"center"},{target:"#part-guide-overview",title:"Вентилятор",content:"Предназначен только лишь для охлаждения комплектующих.",placement:"bottom"},{target:"#fan-guide-airflow",title:"Воздушный поток",content:'Главная характеристика вентилятора. Чем он больше, тем больше охлаждается риг. Каждые 20CFM снижают температуру на 5 градусов, но снижение делится поровну между комплектующими. Подробнее читайте обучение "Для математиков. Охлаждение"',placement:"auto"},{target:"#fan-guide-power",title:"Потребление энергии",content:"Вентиляторы потребляют небольшое кол-во энергии, около 5 Ватт. Но это также стоит учитывать при выборе блока питания.",placement:"auto"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете немного больше о работе вентиляторов в Colorbit.",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),g=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: каркасы",content:"Хотите пройти быстрое обучение по каркасам?",placement:"center"},{target:"#part-guide-overview",title:"Каркас",content:"Предназначен для сборки в нём рига.",placement:"bottom"},{target:"#case-guide-GPUs-count",title:"Вместимость видеокарт",content:"Показывает, сколько видеокарт можно установить в каркас.",placement:"bottom"},{target:"#case-guide-PSUs-count",title:"Вместимость БП",content:"Показывает, сколько блоков питания можно установить в каркас.",placement:"bottom"},{target:"#case-guide-fans-count",title:"Вместимость вентиляторов",content:"Показывает, сколько вентиляторов можно установить в каркас.",placement:"bottom"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете, как выбрать правильный каркас под ваши требования.",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),m=({stopPartGuide:e})=>n(r,{steps:[{target:"#part-guide-start",title:"Обучение: накопители",content:"Хотите пройти быстрое обучение по накопителям?",placement:"center"},{target:"#part-guide-overview",title:"Накопители",content:"Это энергонезависимое устройство, предназначенное для записи, хранения и считывания информации. В игре накопители используются для установки на них ОС и Софта.",placement:"bottom"},{target:"#storage-guide-type",title:"Тип накопителя",content:"Существует несколько типов накопителей: USB, HDD, SSD, NVMe. Каждый из них имеет свои плюсы и минусы.",placement:"auto"},{target:"#storage-guide-type",title:"USB флешки",content:"Хороший вариант для портативного хранения данных, на флешку можно установить и операционную систему, но из-за низкой скорости и нагрузки на NAND-память, которая имеет ограниченное количество циклов перезаписи, она может быстро выйти из строя.",placement:"auto"},{target:"#storage-guide-type",title:"HDD (Hard Disk Drive) ",content:"HDD или жёсткий диск — это устройство хранения данных, использующее магнитные пластины для записи и считывания информации. Винчестеры хорошо подходят для долговременного хранения данных благодаря большой ёмкости и низкой стоимости.",placement:"auto"},{target:"#storage-guide-type",title:"SSD (Solid State Drive)",content:"SSD — это твердотельный накопитель, устройство для хранения данных, которое использует протокол SATA и флэш-память для записи и считывания информации. В отличие от HDD, SSD не имеет движущихся частей, что делает его более быстрым, энергосберегающим и долговечным.",placement:"auto"},{target:"#storage-guide-type",title:"NVMe SSD (Non-Volatile Memory Express)",content:"NVMe — это высокопроизводительный интерфейс и протокол для работы с SSD, которые используют энергонезависимую память. NVMe разработан для достижения максимально возможной скорости и минимизации задержек, благодаря чему значительно превосходит устаревший протокол SATA.",placement:"auto"},{target:"#storage-guide-size",title:"Объём памяти",content:"Показывает объём накопителя в мегабайтах. Чем больше объём, тем больше данных можно на него записать - ОС, различные программы.",placement:"auto"},{target:"#storage-guide-read",title:"Скорость чтения данных",content:"Более высокая скорость чтения данных позволяет быстрее загружать операционную систему и программы, но напрямую на производительность майнинга не влияет.",placement:"auto"},{target:"#storage-guide-write",title:"Скорость записи данных",content:"Более высокая скорость записи данных позволяет быстрее устанавливать операционную систему и программы, но напрямую на производительность майнинга не влияет.",placement:"auto"},{target:"#part-guide-start",title:"Установка ОС и ПО",content:"Для запуска рига необходимо установить на накопитель операционную систему. Также вы можете улучшить риг с помощью необязательного софта — драйвера, клинеры, антивирусы и т.д.",placement:"auto"},{target:"#part-guide-start",title:"🔥Поздравляем",content:"Теперь вы знаете больше. Интересный факт: Самая маленькая ОС Alpine Linux весит 2.67Мб",placement:"center"}],scrollOffset:100,showProgress:!0,showSkipButton:!0,continuous:!0,disableOverlayClose:!0,disableScrollParentFix:!0,styles:a,locale:{back:"Назад",close:"Закрыть",last:"Завершить",next:"Далее",open:"Открыть обучение",skip:"Пропустить"},callback:t=>{(t.status=="finished"||t.status=="skipped")&&e()}}),f=({type:e,isStarted:o=!1,stopPartGuide:t})=>o?e=="GPU"?n(l,{stopPartGuide:t}):e=="CPU"?n(s,{stopPartGuide:t}):e=="motherboard"?n(c,{stopPartGuide:t}):e=="RAM"?n(i,{stopPartGuide:t}):e=="storage"?n(m,{stopPartGuide:t}):e=="PSU"?n(u,{stopPartGuide:t}):e=="case"?n(g,{stopPartGuide:t}):e=="fan"?n(p,{stopPartGuide:t}):null:null;export{f as P};
